    sell_book = []  # (price, arrival_time, id, qty) - sorted by (price, arrival_time)

    arrival_counter = 0
    order_map = {}  # id -> (side, book_index)

    for order in orders:
        arrival_counter += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, book_idx = order_map[order_id]
                if side == 'buy':
                    if 0 <= book_idx < len(buy_book) and buy_book[book_idx][2] == order_id:
                        buy_book.pop(book_idx)
                        # Update indices for remaining orders
                        for oid, (s, idx) in list(order_map.items()):
                            if s == 'buy' and idx > book_idx:
                                order_map[oid] = (s, idx - 1)
                else:  # side == 'sell'
                    if 0 <= book_idx < len(sell_book) and sell_book[book_idx][2] == order_id:
                        sell_book.pop(book_idx)
                        # Update indices for remaining orders
                        for oid, (s, idx) in list(order_map.items()):
                            if s == 'sell' and idx > book_idx:
